with with_windows as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, round(monthly_fee / sum(monthly_fee) over (partition by customer_id), 4) as monthly_fee_share, row_number() over (partition by plan order by monthly_fee desc, id asc) as row_seq, ntile(5) over (partition by plan, customer_id order by monthly_fee desc, id asc) as monthly_fee_bucket from subscriptions) select date_trunc('quarter', end_date) as quarter_start, sum(case when status = 'PAUSED' then monthly_fee_share else 0 end) as paused_monthly_fee_share, max(monthly_fee_bucket) filter (where status = 'PAUSED') as paused_max_monthly_fee_bucket, max(row_seq) filter (where status = 'ACTIVE') as active_max_row_seq from with_windows group by quarter_start order by active_max_row_seq desc nulls first
